codeTemplate.python:
def fToC(f):
  return (f - 32) * 5 / 9

def cToF(c):
  return (c * 9 / 5) + 32

class Temperature:
  def __init__(self, celsius):
    self.celsius = celsius

  def fToC(self, f):
    return fToC(f)

  def cToF(self):
    return cToF(self.celsius)

  def log(self):
    print(f"{self.celsius}°C = {self.cToF()}°F")

t = Temperature(25)
t.log()

